from google.oauth2.credentials import Credentials
from google_auth_oauthlib.flow import Flow
from googleapiclient.discovery import build

from app.auth_jwt import GOOGLE_SCOPES
from app.config import get_settings


def gmail_flow() -> Flow:
    settings = get_settings()
    # PKCE must use the same code_verifier for authorize + token steps. We use two
    # separate Flow instances (start vs callback), so autogenerated PKCE breaks
    # fetch_token. Web clients with a client_secret do not require PKCE.
    return Flow.from_client_config(
        {
            "web": {
                "client_id": settings.gmail_client_id,
                "client_secret": settings.gmail_client_secret,
                "auth_uri": "https://accounts.google.com/o/oauth2/auth",
                "token_uri": "https://oauth2.googleapis.com/token",
                "redirect_uris": [settings.gmail_redirect_uri],
            }
        },
        scopes=GOOGLE_SCOPES,
        redirect_uri=settings.gmail_redirect_uri,
        autogenerate_code_verifier=False,
    )


def authorization_url(state: str) -> str:
    flow = gmail_flow()
    url, _ = flow.authorization_url(
        access_type="offline",
        include_granted_scopes="true",
        prompt="consent",
        state=state,
    )
    return url


def exchange_code(code: str) -> dict:
    flow = gmail_flow()
    flow.fetch_token(code=code)
    creds: Credentials = flow.credentials
    return {
        "access_token": creds.token,
        "refresh_token": creds.refresh_token,
        "expires_at": int(creds.expiry.timestamp()) if creds.expiry else None,
        "token_type": "Bearer",
        "scopes": list(creds.scopes or []),
    }


def fetch_gmail_profile_email(access_token: str) -> str:
    creds = Credentials(token=access_token)
    service = build("gmail", "v1", credentials=creds, cache_discovery=False)
    prof = service.users().getProfile(userId="me").execute()
    return str(prof.get("emailAddress", ""))
